<?php
if (!defined('ABSPATH')) { exit; }
global $wpdb; $table=SPF_Database::table('products'); $lots=SPF_Database::table('lots'); $rows=$wpdb->get_results("SELECT p.*, COALESCE(SUM(l.quantity),0) AS stock_current FROM $table p LEFT JOIN $lots l ON l.product_id=p.id WHERE p.status='active' GROUP BY p.id ORDER BY p.id DESC LIMIT 100",ARRAY_A); $tax_classes=SPF_Tax::classes();
?>
<div class="wrap spf-wrap"><h1><?php esc_html_e('Productos','sistema-para-farmacias'); ?></h1><div class="spf-panel"><h2 id="spf-product-form-title"><?php esc_html_e('Crear producto','sistema-para-farmacias'); ?></h2><form id="spf-product-form" class="spf-grid-form"><input type="hidden" name="action" value="spf_create_product"><input type="hidden" name="product_id" value=""><input type="hidden" name="nonce" value="<?php echo esc_attr(wp_create_nonce('spf_nonce')); ?>"><label><?php esc_html_e('Código de barras','sistema-para-farmacias'); ?><input name="barcode" type="text" inputmode="numeric" value="<?php echo esc_attr(sanitize_text_field(wp_unslash($_GET['barcode']??''))); ?>"></label><div><button class="button" id="spf-scan-product-barcode" type="button"><?php esc_html_e('Escanear código','sistema-para-farmacias'); ?></button></div><label><?php esc_html_e('Nombre','sistema-para-farmacias'); ?><input name="name" type="text" required></label><label><?php esc_html_e('Principio activo','sistema-para-farmacias'); ?><input name="active_ingredient" type="text"></label><label><?php esc_html_e('Laboratorio','sistema-para-farmacias'); ?><input name="laboratory" type="text"></label><label><?php esc_html_e('Categoría','sistema-para-farmacias'); ?><input name="category" type="text"></label><label><?php esc_html_e('Precio compra','sistema-para-farmacias'); ?><input name="purchase_price" type="number" step="0.01" min="0"></label><label><?php esc_html_e('Precio venta','sistema-para-farmacias'); ?><input name="sale_price" type="number" step="0.01" min="0"></label><label><?php echo esc_html(SPF_Config::tax_name()); ?><select name="tax_type"><?php foreach($tax_classes as $code=>$tax_class): ?><option value="<?php echo esc_attr($code); ?>" <?php selected($code,SPF_Tax::default_class()); ?>><?php echo esc_html($tax_class['label']??$code); ?></option><?php endforeach; ?></select></label><label><?php esc_html_e('Stock mínimo','sistema-para-farmacias'); ?><input name="stock_min" type="number" min="0"></label><label><?php esc_html_e('Unidad','sistema-para-farmacias'); ?><input name="unit" type="text" value="<?php esc_attr_e('unidad','sistema-para-farmacias'); ?>"></label><div class="spf-form-actions"><button class="button button-primary" type="submit" id="spf-product-submit"><?php esc_html_e('Guardar producto','sistema-para-farmacias'); ?></button><button class="button" type="button" id="spf-product-cancel-edit" style="display:none;"><?php esc_html_e('Cancelar edición','sistema-para-farmacias'); ?></button></div></form><p class="description"><?php esc_html_e('El stock se gestiona desde Inventario / Lotes. La moneda y los impuestos se obtienen del país configurado.','sistema-para-farmacias'); ?></p><div id="spf-product-result"></div><div id="spf-scanner" class="spf-scanner" style="display:none;"><video id="spf-video" playsinline></video><p id="spf-scanner-status" class="spf-scanner-status"><?php esc_html_e('Apunta al código de barras.','sistema-para-farmacias'); ?></p><button id="spf-stop-scan" class="button" type="button"><?php esc_html_e('Cerrar cámara','sistema-para-farmacias'); ?></button></div></div>
<div class="spf-panel"><h2><?php esc_html_e('Últimos productos','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll"><table class="widefat striped"><thead><tr><th>ID</th><th><?php esc_html_e('Código','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Nombre','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Precio','sistema-para-farmacias'); ?></th><th><?php echo esc_html(SPF_Config::tax_name()); ?></th><th><?php esc_html_e('Stock actual','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Stock mínimo','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Acciones','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?php echo esc_html($row['id']); ?></td><td><?php echo esc_html($row['barcode']); ?></td><td><strong><?php echo esc_html($row['name']); ?></strong></td><td><?php echo esc_html(SPF_Config::money($row['sale_price'])); ?></td><td><?php echo esc_html($tax_classes[$row['tax_type']]['label']??$row['tax_type']); ?></td><td><?php echo esc_html((int)$row['stock_current']); ?></td><td><?php echo esc_html($row['stock_min']); ?></td><td><button type="button" class="button spf-edit-product" data-product='<?php echo esc_attr(wp_json_encode($row)); ?>'><?php esc_html_e('Editar','sistema-para-farmacias'); ?></button> <button type="button" class="button spf-delete-product" data-id="<?php echo esc_attr($row['id']); ?>"><?php esc_html_e('Eliminar','sistema-para-farmacias'); ?></button></td></tr><?php endforeach; ?></tbody></table></div></div></div>
